package com.abhishek.hotelbooking.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<?> notFound(ResourceNotFoundException e){return body(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(ConflictException.class) ResponseEntity<?> conflict(ConflictException e){return body(HttpStatus.CONFLICT,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> m=new HashMap<>(); e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage())); return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"error","Validation failed","fields",m));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return body(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error");} private ResponseEntity<?> body(HttpStatus s,String msg){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s.value(),"error",msg));} }